def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def ranges(n, seps):
        parts = []
        start = 0
        for x in seps:
            if start < x:
                parts.append((start, x))
            start = x + 1
        if start < n:
            parts.append((start, n))
        return parts

    row_parts = ranges(h, sep_rows)
    col_parts = ranges(w, sep_cols)

    panels = []
    for r0, r1 in row_parts:
        for c0, c1 in col_parts:
            panel = [row[c0:c1] for row in grid[r0:r1]]
            panels.append((r0, r1, c0, c1, panel))

    counts = {}
    for _, _, _, _, panel in panels:
        for row in panel:
            for value in row:
                counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    donor = max(
        panels,
        key=lambda p: sum(v != background for row in p[4] for v in row)
    )[4]

    out = [row[:] for row in grid]
    for r0, r1, c0, c1, _ in panels:
        for i, r in enumerate(range(r0, r1)):
            for j, c in enumerate(range(c0, c1)):
                out[r][c] = donor[i][j]
    return out
